import boto3


def speech_client(region, api_key, secret_key):
    return boto3.client('transcribe', region_name=region, aws_access_key_id=api_key, aws_secret_access_key=secret_key)

def create_transcription_request(payload, job_name='transcription'):
    return {
        'displayName': job_name,
        'locale': payload['language_code'],
        'contentUrls': [payload['audio_uri']]
    }


def normalize_transcription_response(response):
    return {
        'job_id': response['self'],
        'status': 'SUBMITTED'
    }

import boto3


def translate_transcript(transcript, source_language, target_language, config=None):
    config = config or {}
    translate_client = boto3.client('translate', region_name=config['region'], aws_access_key_id=config.get('api_key') or os.environ['AWS_ACCESS_KEY_ID'], aws_secret_access_key=config.get('secret_key') or os.environ['AWS_SECRET_ACCESS_KEY'])
    response = translate_client.translate_text(Text=transcript, SourceLanguageCode=source_language, TargetLanguageCode=target_language)
    return {'translated_text': response['TranslatedText']}

import re


def moderate_transcript(transcript):
    # Example moderation: remove profanity
    profanity_pattern = re.compile(r'\b(profanity1|profanity2|profanity3)\b', re.IGNORECASE)
    moderated_transcript = profanity_pattern.sub('[moderated]', transcript)
    return {'moderated_transcript': moderated_transcript}

